sys_ui_action.script:
(function() {
    // 1. Collect the documents that still need reading (collect first, then read)
    var ids = [];
    var doc = new GlideRecord('x_snc_insurance_0_document');
    doc.addQuery('claim_id', current.getUniqueValue());
    doc.addQuery('upload_status', 'uploaded');
    doc.query();
    while (doc.next()) {
        var st = doc.getValue('ai_read_status') || '';
        if (st.indexOf('Read OK') != 0) ids.push(doc.getUniqueValue());
    }

    // 2. Read them one at a time
    if (ids.length == 0) {
        gs.addInfoMessage('All uploaded documents have already been read by AI.');
    } else {
        var reader = new DocumentAIReader();
        var ok = 0, failed = [];
        for (var i = 0; i < ids.length; i++) {
            var result = String(reader.readDocument(ids[i]));
            if (result.indexOf('Read OK') == 0) ok++; else failed.push(result);
        }
        if (failed.length == 0) {
            gs.addInfoMessage('AI read ' + ok + ' document(s). Checks updated.');
        } else {
            gs.addErrorMessage('AI read ' + ok + ' document(s); ' + failed.length +
                               ' failed (' + failed[0] + '). Try again in a minute.');
        }
    }
    action.setRedirectURL(current);
})();
